package com.bishe;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
class DatabaseFeedbackService implements FeedbackStore {
 private final JdbcTemplate jdbc;
 DatabaseFeedbackService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override @Transactional public FeedbackService.Exposure exposure(String userId,List<Long> ids){long now=System.currentTimeMillis();String id=UUID.randomUUID().toString();List<Long> unique=List.copyOf(new LinkedHashSet<>(ids));jdbc.update("INSERT INTO feedback_exposures(id,user_id,created_at) VALUES(?,?,?)",id,userId,now);for(int i=0;i<unique.size();i++)jdbc.update("INSERT INTO feedback_exposure_items(exposure_id,attraction_id,position_no) VALUES(?,?,?)",id,unique.get(i),i);return new FeedbackService.Exposure(id,userId,unique,now);}
 @Override @Transactional public void feedback(String userId,long attractionId,String exposureId,int rating,String comment){if(exposureId!=null && jdbc.queryForObject("SELECT COUNT(*) FROM feedback_exposures e JOIN feedback_exposure_items i ON e.id=i.exposure_id WHERE e.id=? AND e.user_id=? AND i.attraction_id=?",Integer.class,exposureId,userId,attractionId)==0)throw new IllegalArgumentException("评分不属于该次推荐展示");if(exposureId==null)jdbc.update("DELETE FROM user_feedback WHERE user_id=? AND attraction_id=? AND exposure_id IS NULL",userId,attractionId);else jdbc.update("DELETE FROM user_feedback WHERE user_id=? AND attraction_id=? AND exposure_id=?",userId,attractionId,exposureId);jdbc.update("INSERT INTO user_feedback(id,user_id,attraction_id,exposure_id,rating,comment_text,created_at) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID().toString(),userId,attractionId,exposureId,rating,comment==null?"":comment.trim(),System.currentTimeMillis());}
 @Override public FeedbackService.Summary summary(){int ratings=jdbc.queryForObject("SELECT COUNT(*) FROM user_feedback",Integer.class),exposures=jdbc.queryForObject("SELECT COUNT(*) FROM feedback_exposures",Integer.class);int participants=jdbc.queryForList("SELECT user_id FROM feedback_exposures UNION SELECT user_id FROM user_feedback",String.class).size();int judged=jdbc.queryForObject("SELECT COUNT(*) FROM user_feedback WHERE exposure_id IS NOT NULL",Integer.class),positive=jdbc.queryForObject("SELECT COUNT(*) FROM user_feedback WHERE exposure_id IS NOT NULL AND rating>=4",Integer.class);Double avg=jdbc.queryForObject("SELECT AVG(rating) FROM user_feedback",Double.class);return new FeedbackService.Summary(ratings,participants,exposures,judged,positive,judged==0?null:(double)positive/judged,avg);}
 @Override @Transactional public void delete(String userId){jdbc.update("DELETE FROM user_feedback WHERE user_id=?",userId);jdbc.update("DELETE FROM feedback_exposure_items WHERE exposure_id IN (SELECT id FROM feedback_exposures WHERE user_id=?)",userId);jdbc.update("DELETE FROM feedback_exposures WHERE user_id=?",userId);}
}
